// Whitelist explícita obrigatória (regra 13/08, ver auditoria de Data
// Exposure): nunca passthrough do jsonb da RPC, mesmo quando ela hoje só
// devolve campos seguros. valor_total já vem somado a partir dos itens
// reais (nunca da coluna carrinho.valor_total cacheada) -- a RPC garante
// isso, aqui só reconstruímos o payload campo a campo.
const row = $input.first()?.json?.carrinho || { itens: [], valor_total: 0 };

const itens = (row.itens || []).map(i => ({
  produto_id: i.produto_id,
  nome: i.nome,
  quantidade: i.quantidade,
  preco_unitario: i.preco_unitario,
  subtotal: i.subtotal,
}));

return [{ json: {
  vazio: itens.length === 0,
  itens,
  valor_total: row.valor_total,
} }];

function tryGet(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}
const trigger = $('When Executed by Another Workflow').item.json;
const resultado = tryGet('Montar Resultado');
const blacklist = ['p_empresa_id','p_cliente_id','p_conversa_id','p_mensagem_id','p_atendimento_id'];
const input = {};
for (const k of Object.keys(trigger || {})) {
  if (!blacklist.includes(k)) input[k] = trigger[k];
}
return [{ json: {
  empresa_id: trigger.p_empresa_id,
  conversa_id: trigger.p_conversa_id || null,
  mensagem_id: trigger.p_mensagem_id || null,
  atendimento_id: trigger.p_atendimento_id || null,
  tool_nome: 'consultar_carrinho',
  detalhes: JSON.stringify({ input, output: resultado }),
  resultado_original: resultado,
} }];

